function stripHTML(html) {
  if (!html) return '';
  return html.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ');
}

// Remove signature blocks like '--', '*Name*', or lines starting with 'Best,'
function removeSignature(text) {
  if (!text) return '';
  // Stop at the first common signature marker, if present
  const sigPatterns = [
    /\n-- ?\n/,        // --\n
    /\nBest[ ,].*\n/i, // Best, or Best regards,
    /\nKind regards[ ,].*\n/i,
    /\nThanks[ ,].*\n/i,
    /\nSincerely[ ,].*\n/i,
    /\n\*.*\*\n/,     // e.g. \n*Michelle Ricketts*\n
  ];
  let index = text.length;
  for (const pattern of sigPatterns) {
    const match = text.match(pattern);
    if (match && match.index < index) index = match.index;
  }
  return text.slice(0, index).trim();
}

function extractOriginal(text) {
  if (!text) return '';
  // Find the earliest marker of quoted thread
  const quotePatterns = [
    /\nOn .*wrote:/i,
    /\nFrom:/i,
    /\n-----Original Message-----/i,
    /\n-+ Forwarded message -+/i,
    /\n>+/i, // Lines starting with >
  ];
  let index = text.length;
  for (const pattern of quotePatterns) {
    const match = text.match(pattern);
    if (match && match.index < index) index = match.index;
  }
  let original = text.slice(0, index).trim();
  original = removeSignature(original);
  return original.trim();
}

const emails = $json.data || [];
const separator = '▃▃▃▃▃▃▃▃▃▃▃▃';

let history = emails.map(email => {
  let body = email.text_body && email.text_body.trim()
    ? email.text_body
    : stripHTML(email.html_body);

  // Only keep the original message, remove signature
  body = extractOriginal(body);

  // Ignore empty
  if (!body) return null;

  return body + '\n' + separator + '\n';
}).filter(Boolean).join('\n');

return [{ json: { history } }];

