// Grab the array from the webhook node
const customVariables = $('Webhook').first().json.body.data.lead.custom_variables;

// Initialize result vars
let linkedin = null;
let company_name = null;

// Loop through the custom variables
for (const item of customVariables) {
  // LinkedIn
  if (item.name && item.name.toLowerCase().includes('linkedin')) {
    linkedin = item.value;
  }

  // Company name: match "company", "comp", or "company_name"
  if (item.name) {
    const lower = item.name.toLowerCase();
    if (
      lower === 'company' ||
      lower === 'comp' ||
      lower === 'company_name'
    ) {
      company_name = item.value;
    }
  }
}

// Output as variables for next node
return [
  {
    json: {
      linkedin,
      company_name,
    },
  },
];

